[
  {
    "path": "state/lessons/2026-07-19-a-safe-to-drop-stash-on-a-shared-tree-ca-7cd27d453581.yaml",
    "frontmatter": {
      "created": "2026-07-19",
      "title": "A 'safe to drop' stash on a shared tree can hold the only copy of load-bearing wiring",
      "body": "On a shared working tree, a concurrent agent/session may git-stash your uncommitted TRACKED edits (op registrations) while leaving untracked new files, or commit your untracked op as an 'orphaned in-flight' sweep. This session: a prior executor labeled a 'wip probe' stash 'redundant, safe to drop' — it actually held the ONLY copy of the op's registration edits (ipc._OP_KEY_SCOPE + ops/__init__ eager-import + _registry_map). Dropping it blindly would have shipped the op as unreachable dead code. The op's own unit tests PASSED without the registrations because they import the module directly, never exercising the registry — green masked the gap. Recovery: git stash show -p before any drop; git checkout HEAD on the conflicted registry files revealed a sibling had ALSO committed my op at the wrong (superseded) version.",
      "status": "open",
      "scope": "universal",
      "from_repo": "claude-central-em",
      "proposed_target": "docs/wiki/concurrent-em-hazards.md",
      "evidence": "claude-klabauter 1d8ae658 (correct), a69ef826 (sibling orphaned-in-flight sweep), example-doctrine-repo c47b0268",
      "trigger": "Committing a cross-repo op on a shared work/* branch with sibling sessions concurrently active on the same registries",
      "why": "Unit tests that import a module directly do not exercise its registry/dispatch wiring, so missing registration passes tests but ships dead code; a stash label from another agent is not a safety proof",
      "how_to_apply": "git stash show -p before dropping any stash you did not create; after any stash/checkout churn on a shared tree, grep the registry/dispatch/import surfaces for the new symbol to confirm wiring survived — do not trust green tests alone",
